"use strict";(self.webpackChunktoum_docs=self.webpackChunktoum_docs||[]).push([["42"],{8052(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"update-179","metadata":{"permalink":"/docs.toum.gg/blog/update-179","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-10-18-update-179.md","source":"@site/blog/first-release/2026-10-18-update-179.md","title":"Mira v1.7.9 Beta 1 Update","description":"Town of Us: Mira has updated to v1.7.9 Beta 1!","date":"2026-10-18T00:00:00.000Z","tags":[],"readingTime":1.86,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-179","title":"Mira v1.7.9 Beta 1 Update","authors":["moon"]},"unlisted":false,"nextItem":{"title":"Mira v1.7.3 Update","permalink":"/docs.toum.gg/blog/update-173"}},"content":"## Town of Us: Mira has updated to [v1.7.9 Beta 1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.9-beta1)!\\r\\n\\r\\nThis update includes bug fixes and additional changes. See the full changelog below.\\r\\n\\r\\n:::info[version change]\\r\\n\\r\\n<big>**This update runs on **v19** of Among Us and requires a fresh install!**</big>\\r\\n\\r\\n:::\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Ambusher\'s animation no longer breaks.\\r\\n- Fix Parasite not being able to open meeting chat.\\r\\n- Fixed Escapist recall sprite layering.\\r\\n- Fixed Miner vent layering.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Fixed \\"frozen\\" stones not actually appearing as stone.\\r\\n- Chef keeps track of disconnected served players to prevent an impossible win.\\r\\n</details></details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Disable Submerged button for Ghostwalkers.\\r\\n- Fixed loading issues with Submerged. Note that this means every player is required to have it when using it.\\r\\n- Fixed issues with draft not giving roles or simply not listening to other player picks.\\r\\n- Fixed map decoration on Skeld.\\r\\n- Fixed save data not saving.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements, Additions & Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- Ambassador\'s Selection menu now has two circles of roles to display more at once.\\r\\n- Zoom is no longer easy to trigger on mobile.\\r\\n- Prevent zooming in draft.\\r\\n- Fix issues with custom text icons clipping in UI.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Balancing Tweaks**</summary>\\r\\n- By default, Hunter will need to wait a round before they can kill a caught player without being punished for it if they are crew.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- Added implementation for the new match info guide, as well as a temporary toggle.\\r\\n- Added the ability to see chat notifications outside of the lobby.\\r\\n- Added settings to toggle sabotages when dead and when too few players are alive.\\r\\n- Added Achievements Support (bundled in this release).\\r\\n  Added basic Mutually-Exclusive role buckets.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n- Rainbow color is a bit slower and is more optimized now.\\r\\n- Added Nameplates and Visor support via Corsac Cosmetics, requiring it for all future releases.\\r\\n- Removed Classic Mode for Players. Innersloth\'s changes have made it unfeasible to try getting it to work again.\\r\\n</details></details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-173","metadata":{"permalink":"/docs.toum.gg/blog/update-173","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-09-06-update-173.md","source":"@site/blog/first-release/2026-09-06-update-173.md","title":"Mira v1.7.3 Update","description":"Town of Us: Mira has updated to v1.7.3!","date":"2026-09-06T00:00:00.000Z","tags":[],"readingTime":1.65,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-173","title":"Mira v1.7.3 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"Mira v1.7.9 Beta 1 Update","permalink":"/docs.toum.gg/blog/update-179"},"nextItem":{"title":"Mira v1.7.2 Update","permalink":"/docs.toum.gg/blog/update-172"}},"content":"## Town of Us: Mira has updated to [v1.7.3](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.3)!\\r\\n\\r\\nThis update includes bug fixes and additional changes. See the full changelog below.\\r\\n\\r\\n:::info[version change]\\r\\n\\r\\n<big>**This update runs on **v18** of Among Us and requires a fresh install!**</big>\\r\\n\\r\\n:::\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Crewmates**</summary>\\r\\n- Sheriff: Fixed broken punishment explanation in tab description.\\r\\n- Altruist: Fixed broken tab description.\\r\\n- Mirrorcaster: Magic Mirrors no longer stay permanently if the Mirrorcaster is converted.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Impostors**</summary>\\r\\n- Morphling: If configured, the Morph ability uses are no longer able to go less than 0.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Neutrals**</summary>\\r\\n- Survivor: Survivor no longer takes wins away from Impostors.\\r\\n- Plaguebearer: Adjusted checks to rule out the possibility of duplicate plague on a player.\\r\\n- Werewolf: Werewolf\'s short-burst kill cooldown is no longer affected by cooldown changes.\\r\\n- Chef: Added safeguards against the possible occurrence of missing dead bodies, breaking the win conditions.\\r\\n</details></details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Draft Mode & Other Bug Fixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Draft Mode Bug Fixes**</summary>\\r\\n- Target-based roles like Fairy and Executioner have targets assigned properly again.\\r\\n- Concurrent picks no longer removes picks from other player.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Other Bug Fixes**</summary>\\r\\n- Fixed bad AU code causing anti-cheat to kick non-hosts if they voted for someone who died in the meeting.\\r\\n- Fixed non-classic roles appearing in the settings menu.\\r\\n- Fixed missing causes of death appearing due to locale system changes.\\r\\n- Fixed Assailant Modifier Options text.\\r\\n- Fixed kill cooldown for Impostors not being based on overall cooldown offsets.\\r\\n</details></details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Other Changes**</summary>\\r\\n- Added Ghostwalker Auto-Venting setting upon spawning under Game Mechanics.\\r\\n- Added Judge\'s punishment as a setting for Prosecutor\'s punishment (now the default).\\r\\n- Reshuffling in Draft Mode gives you spare time to pick if necessary.\\r\\n</details></details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-172","metadata":{"permalink":"/docs.toum.gg/blog/update-172","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-09-04-update-172.md","source":"@site/blog/first-release/2026-09-04-update-172.md","title":"Mira v1.7.2 Update","description":"Town of Us: Mira has updated to v1.7.2!","date":"2026-09-04T00:00:00.000Z","tags":[],"readingTime":2.3,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-172","title":"Mira v1.7.2 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"Mira v1.7.3 Update","permalink":"/docs.toum.gg/blog/update-173"},"nextItem":{"title":"Mira v1.7.1 Update","permalink":"/docs.toum.gg/blog/update-171"}},"content":"## Town of Us: Mira has updated to [v1.7.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.2)!\\r\\n\\r\\nThis update includes bug fixes and additional changes. See the full changelog below.\\r\\n\\r\\n:::info[version change]\\r\\n\\r\\n<big>**This update runs on **v18** of Among Us and requires a fresh install!**</big>\\r\\n\\r\\n:::\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Haunter: Dead killers no longer get an arrow to a revealed Haunter.\\r\\n- Deputy: No longer guessable after being revealed.\\r\\n- Prosecutor: Prosecute uses text is no longer broken.\\r\\n- Time Lord: Final evil being revived no longer ends the game with a crewmate win.\\r\\n- Swapper: Swapped players properly carry over their colorblind text.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Doomsayer: If Doomsayer continues the game and is supposed to win the game when all guesses are completed, the game will no longer end in a crewmate win.\\r\\n- Doomsayer: Guess information is properly tracked for other players.\\r\\n- Plaguebearer: Pestilence transformation is fixed for edge cases.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifiers**</summary>\\r\\n- Deadly Quota: The last kill of the game is properly counted towards the quota now.\\r\\n- Overclocker: Overclock no longer grants impostors a 0 second kill cooldown.\\r\\n- Tiebreaker: Tiebreaker no longer continues the game while dead.\\r\\n- Noisemaker: Noisemaker no longer stays lingering even when a body is cleaned up.\\r\\n- Bait: Fixed bait reports occurring even if a body was cleaned up in time.\\r\\n</details></details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Draft Mode & Other Bug Fixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Draft Mode Bug Fixes**</summary>\\r\\n- Amount of choices is no longer affected by the number of players present.\\r\\n- Shuffling no longer reduces the number of options you get.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Concealed changes such as Ambusher, Morphling, and Swooper no longer carry into meetings.\\r\\n- Added support for the latest Level Imposter release.\\r\\n- Fixed broken Submerged patching.\\r\\n- Neutral Killers no longer take full priority over win conditions. This now fixes game draws.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Notable Changes**</summary>\\r\\n- Mod now runs on Among Us v18.0.x.\\r\\n- Prosecutor, Politician, Mayor, and Hypnotist have now switched to the new meeting abilities system.\\r\\n- The Win Condition system has been rewritten. Neutral Benigns are treated as majority Crewmates if at least two main factions (Crew, Imps, NKs) exist. Otherwise, they will be ignored from win checks. Survivor can also win solo if only NBs remain.\\r\\n- Vampire is counted as two Neutral Killing slots under Draft Mode now.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Changes**</summary>\\r\\n- By default, Janitor can clean and kill separately only if they\'re by themselves.\\r\\n- Mayor and Deputy will still say their role on their name even if they are converted.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-171","metadata":{"permalink":"/docs.toum.gg/blog/update-171","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-08-06-update-171.md","source":"@site/blog/first-release/2026-08-06-update-171.md","title":"Mira v1.7.1 Update","description":"Town of Us: Mira has updated to v1.7.1!","date":"2026-08-06T00:00:00.000Z","tags":[],"readingTime":1.88,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-171","title":"Mira v1.7.1 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"Mira v1.7.2 Update","permalink":"/docs.toum.gg/blog/update-172"},"nextItem":{"title":"Mira v1.7.0 Update","permalink":"/docs.toum.gg/blog/update-170"}},"content":"## Town of Us: Mira has updated to [v1.7.1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.1)!\\r\\n\\r\\nThis update includes bug fixes and some rolechanges. See the full changelog below.\\r\\n\\r\\n:::danger[IMPORTANT]\\r\\n\\r\\n<big>**This update runs on **v17.4** of Among Us and requires a fresh install.**</big>\\r\\n\\r\\nDo not just replace files as this will cause issues.\\r\\n:::\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Lookout shuffles its watch findings properly again.\\r\\n- Seer Reveal mode checks its options properly.\\r\\n- Converted Jailor no longer leaves jailee in a broken state.\\r\\n- Knighted Mayor no longer gets double votes.\\r\\n- Imitator no longer shows (Imi) while dead.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Ambassador retrain is consistently functional on teammates now.\\r\\n- Ambassador retrain no longer sets the trainee\'s kill cooldown to 0.\\r\\n- Traitor no longer shows (Traitor) while dead.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Executioner, Fairy, and Inquisitor check for disconnected targets properly.\\r\\n- Fixed errors thrown by unshattered Medusa stones that broke the whole game.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifiers**</summary>\\r\\n- Celebrity shows death by the Spectre properly.\\r\\n- Circumvent uses are no longer bypassed with a meeting.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Draft Mode & Other Bug Fixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Draft Mode Bug Fixes**</summary>\\r\\n- Draft no longer softlocks if Host disconnects.\\r\\n- Draft UI is no longer left behind during role intro or when leaving mid-draft.\\r\\n- Alignment Mode no longer shows the actual faction instead.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- End Game Summary shows role icons for disconnected players.\\r\\n- Fixed the biggest source of memory leaking.\\r\\n- Fixed crashing for Epic Games and Xbox Game Pass users.\\r\\n- Game Options should no longer desync when initially joining.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmate Changes**</summary>\\r\\n- Prosecutor now stops swaps from happening.\\r\\n- Monarch can now optionally reveal knighting in the meeting.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors Changes**</summary>\\r\\n- Venerer can now cancel their ability early.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals Changes**</summary>\\r\\n- Victims of Executioner Torment, Jester Haunt, and Spectre Spook are publicly announced.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Changes**</summary>\\r\\n- Added Role Icon on Role Reveal screen local toggle.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-170","metadata":{"permalink":"/docs.toum.gg/blog/update-170","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-08-02-update-170.md","source":"@site/blog/first-release/2026-08-02-update-170.md","title":"Mira v1.7.0 Update","description":"Town of Us: Mira has updated to v1.7.0!","date":"2026-08-02T00:00:00.000Z","tags":[],"readingTime":6.17,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-170","title":"Mira v1.7.0 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"Mira v1.7.1 Update","permalink":"/docs.toum.gg/blog/update-171"},"nextItem":{"title":"v1.6.3 Update","permalink":"/docs.toum.gg/blog/update-163"}},"content":"## Town of Us: Mira has updated to [v1.7.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.0)!\\r\\n\\r\\nThis update is packed with **big changes and new additions**, including:\\r\\n\\r\\n- Draft Mode is now part of the base mod!\\r\\n- A new Impostor and a new Crewmate role!\\r\\n- 2 new modifiers!\\r\\n- A new pet!\\r\\n\\r\\nAlso included are **a number of changes to existing roles and modifiers**, as well as bug fixes and improvements. See the full changelog below.\\r\\n\\r\\n:::danger[IMPORTANT]\\r\\n\\r\\n<big>**This update runs on v17.4 of Among Us and <u>requires a full reinstall</u>.**</big>\\r\\n\\r\\nDo not just replace files as this will cause issues.\\r\\n:::\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### New Roles!\\r\\n\\r\\n- The **Barkeeper** is a _Crewmate Support_ role that can drink with others to roleblock them. They may also spill a drink to speed up or slow down other players.\\r\\n\\r\\n- The **Bootlegger** is an _Impostor Support_ role that can drink with others to roleblock them. Once a player is roleblocked three times, they will die of poison.\\r\\n\\r\\n---\\r\\n\\r\\n### New Modifiers!\\r\\n\\r\\n- **Drunk** (Universal) \u2014 Your controls are permanently inverted. You are also immune to normal roleblocks.\\r\\n- **Overclocker** (Assailant) \u2014 You may decrease your cooldowns at the cost of longer cooldowns once your Overclock is over. After an additional round, your cooldowns will normalize.\\r\\n\\r\\n---\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Investigator footprints are layered correctly for every map.\\r\\n- Medium\'s Spirit displays arrows for everyone properly.\\r\\n- \\"Medium can Identify\\" setting properly makes ghosts anonymous.\\r\\n- Mystic arrows no longer appear if their duration is 0 seconds.\\r\\n- Swapper and Prosecutor vote changes reflect on Executioner, Jester, and Hunter.\\r\\n- Disconnected Medics will not leave their shields behind on players anymore.\\r\\n- Disconnected players that are protected will return uses to Medic, Mirrorcaster, and Warden.\\r\\n- Noisemaker will properly check for rotting bodies or stoned players.\\r\\n- Imitator priority is fixed for roles like Forensic.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Venerer abilities no longer reset from an additional kill.\\r\\n- Added checks for Ambassador and Traitor to throw warnings when no roles are available.\\r\\n- Miner explosion no longer appears on invisible vent.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Executioner and Doomsayer leave notifications appear properly for everyone now.\\r\\n- Doomsayer killing all victims at once setting is fixed, and no longer kills just one player.\\r\\n- Glitch hack no longer prevents killers from being able to kill for the remainder of the game.\\r\\n- Inquisitor will win solo in a 1v1 and will not take away wins in a 1v1 with dead heretics ([PR #225](https://github.com/AU-Avengers/TOU-Mira/pull/225)).\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifiers**</summary>\\r\\n- Crewpostor Vigilante can no longer guess other impostors.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Fixed problems with the End Game Timer breaking and erroring.\\r\\n- Submerged will no longer break in the role reveal.\\r\\n- Neutral Wildcard no longer duplicates the amount of each neutral present ([PR #191](https://github.com/AU-Avengers/TOU-Mira/pull/191)).\\r\\n- Wiki hyperlinks will check for gamemode-specific roles properly.\\r\\n- Full support for Among Us v17.4.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmate Changes**</summary>\\r\\n- Lookout by default sees who interacts, rather than what roles interact.\\r\\n- In the \\"See Players\\" mode, Lookout will not be able to see Bomber or any other indirect attacks.\\r\\n- Seer can optionally only use their ability once per round and/or compare each player once per game ([PR #231](https://github.com/AU-Avengers/TOU-Mira/pull/231)).\\r\\n- Deputy, by default, will warn their camped target\'s killer about a Deputy existing ([PR #209](https://github.com/AU-Avengers/TOU-Mira/pull/209)).\\r\\n- Deputy will now reveal themselves upon a successful shot.\\r\\n- Prosecutor now has a full-screen animation for prosecutes.\\r\\n- Time Lord, by default, will revive players for a single round, and make them die after the next meeting ends.\\r\\n- Medic now sees \\"Darker / Lighter\\" on all players rather than just on living players.\\r\\n- Transporter now uses a single multi-select menu for transporting players.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors Changes**</summary>\\r\\n- Swooper can optionally be untrackable while swooping. ([PR #201](https://github.com/AU-Avengers/TOU-Mira/pull/201)).\\r\\n- Blackmailed players no longer immediately skip if too many players are alive.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals Changes**</summary>\\r\\n- Doomsayer shows guessing progress next to their name.\\r\\n- Doomsayer no longer sees disabled roles in their feedback\\r\\n- Jester has an optional limited duration and cooldown adjustment for venting ([PR #237](https://github.com/AU-Avengers/TOU-Mira/pull/237)).\\r\\n- Jester can now Poke players, triggering roles like Warden, Cleric, Herbalist, Lookout, and more ([PR #205](https://github.com/AU-Avengers/TOU-Mira/pull/205)).\\r\\n- **Soul Collector has been permanently replaced by Medusa.** This rework makes players slowly fade into stone, and allows Transporters to still interact with them to an extent. Non-shattered stones will remain throughout rounds as evidence.\\r\\n- Chef shows feeding progress on their name.\\r\\n- Inquisitor marks off any Heretic roles that have died in their role tab.\\r\\n- Inquisitor now has a Heretic progress count next to their name.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Changes**</summary>\\r\\n- Tiebreaker now stalls the game as a solo Crewmate, or as a Jester / Executioner in a 1v1 / 1v2.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Changes**</summary>\\r\\n- Unity Rich Text is no longer allowed on players to prevent issues with tag abuse ([PR #206](https://github.com/AU-Avengers/TOU-Mira/pull/206)).\\r\\n- Lobby Rules are now limited to being displayed at 3-second intervals due to malicious players who sell cheat mods to disrupt lobbies.\\r\\n- Task tracking is mostly up for preference now, with the host simply toggling if other task amounts can be seen by the dead.\\r\\n- All local game options are moved to 6 different categories.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Additions & Improvements**</summary>\\r\\n  \\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- @idkimneil\'s Draft Mode is now part of the base mod. This can be toggled in the Role Distribution settings.\\r\\n- Added Perfect Comms (Prox-Chat) role integration on the mod itself ([PR #226](https://github.com/AU-Avengers/TOU-Mira/pull/226)) **- REQUIRES UPDATE TO PERFECT COMMS 4.1.7 OR NEWER!**\\r\\n- Added **Overclocker**, an Assailant modifier that speeds up cooldowns for more general killers but then slows cooldowns afterwards.\\r\\n- Added **Drunk**, a Universal modifier that also has roleblock immunity.\\r\\n- **Barkeeper** joins the Crewmate Support alignment with a standard roleblock ability and also a spill ability, changing player speed for anyone who steps in it.\\r\\n- **Bootlegger** joins the Impostor Support alignment with a roleblock ability that slowly turns into poison.\\r\\n- Added \\"Full Save Cooldown Multiplier\\" for full protective roles.\\r\\n- Added the all-important Flopster pet (she\'s a little silly).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- Options for roles and modifiers display changes in a similar fashion to vanilla\'s option notifications.\\r\\n- Hovering over the role list text in the lobby is now adjusted for the corresponding gamemode selected.\\r\\n- Player text in meetings will now shrink depending on the amount of text within it.\\r\\n- Meeting kill animations are synced for every player.\\r\\n- In-Game Wiki will no longer stutter when reopening the roles search tab.\\r\\n- Abilities disabled on round one now show that they are, in fact, disabled for that reason.\\r\\n- More roles have additional visual and audio work.\\r\\n- Game Modifiers display if they are guessable within their wiki entries.\\r\\n- Roles now have their icons displayed in text.\\r\\n- Wiki Hyperlinks in text will now display their corresponding icons.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-163","metadata":{"permalink":"/docs.toum.gg/blog/update-163","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-06-13-update-163.md","source":"@site/blog/first-release/2026-06-13-update-163.md","title":"v1.6.3 Update","description":"Town of Us: Mira has updated to v1.6.3!","date":"2026-06-13T00:00:00.000Z","tags":[],"readingTime":1.93,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-163","title":"v1.6.3 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"Mira v1.7.0 Update","permalink":"/docs.toum.gg/blog/update-170"},"nextItem":{"title":"TOU:R v6.0.0","permalink":"/docs.toum.gg/blog/update-600"}},"content":"## Town of Us: Mira has updated to [v1.6.3](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.3)!\\r\\n\\r\\n**This version runs on the latest version of Among Us (v17.4). A fresh install is recommended to ensure no conflicts with old files!**\\r\\n\\r\\nSee the full changelog below.\\r\\n\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Officer now sees Prosecutor as a valid killer.\\r\\n- Monarch is no longer immune to basic interactions when they have a shield.\\r\\n- Cleric Barrier duration is no longer tied to its cooldown.\\r\\n- Warden no longer resets cooldowns to one second.\\r\\n- Engineer and Plumber interact with vents in a more optimized fashion. (PR #190 by @TheDavSmasher)\\r\\n- Plumber barricades prevent all venters from entering properly. (PR #192 by @TheDavSmasher)\\r\\n- Sentry Cameras are no longer placed below the map.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Shapeshifter now inherits fake shields on players, like how Morphling / Glitch do.\\r\\n- Parasite and Puppeteer can interact with Ladders, Platforms, and Ziplines properly. [PR #176, DrFreezyYT](https://github.com/AU-Avengers/TOU-Mira/pull/176).\\r\\n- Pet Button no longer interferes with forced player map interactions.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Arsonist douse count is no longer more than intended.\\r\\n- Executioner can no longer torment when their target becomes evil.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Pets tab now says \\"Pets\\" rather than \\"Hats.\\"\\r\\n- Directly clicking on security utilities like Admin is no longer possible if task requirements aren\'t met.\\r\\n- End Game Timer is no longer broken.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes and Improvements**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n- Miner now places Polus vents and has an animation paired with it.\\r\\n- By default, Sonar now uses Heartbeats instead of arrows to keep track of players.\\r\\n- Haunter now marks players with a dark red name when they are revealed.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- Glitch, Morphling, and Swooper now have better vent settings.\\r\\n- UI changes are far more optimized now.\\r\\n- Destroyed animations are now cleared from memory properly.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- TOU Mira: Legacy is now a part of the main mod.\\r\\n- Role Name placement is now configurable in terms of size and position.\\r\\n- Added configurable mod stamp placement.\\r\\n- Added \\"TV Show\\" style for Skeld visuals.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-600","metadata":{"permalink":"/docs.toum.gg/blog/update-600","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/TOUR Updates/2026-06-13-TOUR-600.md","source":"@site/blog/TOUR Updates/2026-06-13-TOUR-600.md","title":"TOU:R v6.0.0","description":"Town of Us: Reactivated is so back!","date":"2026-06-13T00:00:00.000Z","tags":[],"readingTime":0.86,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-600","title":"TOU:R v6.0.0","authors":["moon"]},"unlisted":false,"prevItem":{"title":"v1.6.3 Update","permalink":"/docs.toum.gg/blog/update-163"},"nextItem":{"title":"v1.6.2 Update","permalink":"/docs.toum.gg/blog/update-162"}},"content":"## [Town of Us: Reactivated is so back!](https://github.com/AU-Avengers/Town-Of-Us-Reactivated)\\r\\n\\r\\nOur very own [Atony](https://github.com/AtonyGit) has officially updated **Town of Us: Reactivated** to run on the latest version of Among Us!\\r\\n\\r\\nGoing forward, updates for TOU:R will be for compatibility and quality of life. New roles and modifiers will **not** be added to this release. See the changelog below for more.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changelog**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changelog**</summary>\\r\\n\\r\\n- Ported the mod over to the latest releases of Among Us.\\r\\n- Added Android support via Starlight.\\r\\n- Renamed mod metadata to prevent confusion with TOU Mira.\\r\\n- Improved Hats Selection Menu.\\r\\n- Added new hats from TOU Mira.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Notes**</summary>\\r\\n- Presets are now located in `C:\\\\Users\\\\%user%\\\\AppData\\\\LocalLow\\\\Innersloth\\\\Among Us\\\\reactivated_presets`. Make sure to move them over once reaching the main menu.\\r\\n- Auto-updater will not currently be used for Reactivated, as it has proven to be unreliable at times.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-162","metadata":{"permalink":"/docs.toum.gg/blog/update-162","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-05-11-update-162.md","source":"@site/blog/first-release/2026-05-11-update-162.md","title":"v1.6.2 Update","description":"Town of Us: Mira has updated to v1.6.2!","date":"2026-05-11T00:00:00.000Z","tags":[],"readingTime":2.31,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-162","title":"v1.6.2 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"TOU:R v6.0.0","permalink":"/docs.toum.gg/blog/update-600"},"nextItem":{"title":"v1.6.1 Update","permalink":"/docs.toum.gg/blog/update-161"}},"content":"## Town of Us: Mira has updated to [v1.6.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.2)!\\r\\n\\r\\nThis update includes bug fixes and improvements: see the full changelog below.\\r\\n\\r\\nAs always, be sure to do a fresh install!\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n**Known Bugs:**\\r\\n\\r\\n- Neutral Wildcard may duplicate the amount of each neutral present if any selected slots are wildcards.\\r\\n- Ghostwalkers are sometimes unable to use the Zipline, Platform, or Ladders.\\r\\n\\r\\n**Known Hide n Seek Bugs:**\\r\\n\\r\\n- The Seeker is missing animations for the hiders.\\r\\n- Hiders ignore their vent uses.\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Medium\'s Spirit movement no longer carries over from Time Lord rewinds.\\r\\n- Killers now get arrows that point to the Haunter when they complete their tasks.\\r\\n- Medic no longer breaks when a player is protected by multiple Medics. Only one Medic will be flashed at a time.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Venerer no longer displays its effects as \\"Visual\\" modifiers.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Glitch no longer resets mimic cooldowns for other Glitches.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Changing the UI scale mid-game no longer breaks the UI at the top right.\\r\\n- Chat messages are now capped to a maximum of 20 public and 20 private chat messages to prevent crashing.\\r\\n- Roles are no longer revealed immediately upon death.\\r\\n- Pets are removed based on settings properly.\\r\\n- Celebrity\'s cause of death now displays all causes of death.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Other Bugfixes**</summary>\\r\\n- Impostor replaced by a Crewpostor can no longer see their previous task text.\\r\\n- Camo Comms no longer shows other player names when revived.\\r\\n- Doors can be set to Skeld doors or be flat-out removed properly on Submerged.\\r\\n- Private Chat is no longer broken.\\r\\n- Players disconnecting from the lobby no longer breaks the player count.\\r\\n- Disconnected players no longer leak their role color.\\r\\n- Submerged and Level Impostor no longer break when loading base game map assets.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes and Improvements**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n- Monarch will no longer be able to change their shield appearance, and is now always Grey. A future patch will allow further configuration, but not to the same degree as before with Warden / Cleric flashing.\\r\\n- Seer can no longer compare revealed players.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- It is now possible to disable any host keybind if you tend to misclick.\\r\\n- Survivor, Fairy, and 1st Round Shield protection will flash grey, as a way to not appear unresponsive.l/173).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- Two custom pets have been added\\r\\n- Game Mechanic Option: All Shields Flash Anonymously.\\r\\n- Top-Right UI can now be scaled up and down.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-161","metadata":{"permalink":"/docs.toum.gg/blog/update-161","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-05-02-update-161.md","source":"@site/blog/first-release/2026-05-02-update-161.md","title":"v1.6.1 Update","description":"Town of Us: Mira has updated to v1.6.1!","date":"2026-05-02T00:00:00.000Z","tags":[],"readingTime":2.55,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-161","title":"v1.6.1 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"v1.6.2 Update","permalink":"/docs.toum.gg/blog/update-162"},"nextItem":{"title":"v1.6.0 Update","permalink":"/docs.toum.gg/blog/update-160"}},"content":"## Town of Us: Mira has updated to [v1.6.1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.1)!\\r\\n\\r\\nThis update includes bug fixes and improvements: see the full changelog below.\\r\\n\\r\\nAs always, be sure to do a fresh install!\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n**Known bugs with this update:**\\r\\n\\r\\n- Controlled players (via Parasite/Puppeteer) appear to be stuck in a walk cycle when they are walking onto a wall, showing they are under control.\\r\\n- Neutral Wildcard may duplicate the amount of each neutral present if any selected slots are wildcards.\\r\\n- Ghostwalkers are sometimes unable to use the Zipline, Platform, or Ladders.\\r\\n- When Haunter finishes their tasks, sometimes the Impostors will not get an arrow to the Haunter, essentially screwing them over.\\r\\n- Pets aren\'t removed based on settings properly.\\r\\n- Medic Shield still doesn\'t get shattered properly with the settings.\\r\\n\\r\\n**Known Hide and Seek Bugs:**\\r\\n\\r\\n- The Seeker is missing animations for the Hiders.\\r\\n- Hiders ignore their vent uses.\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Officer no longer breaks across game sessions.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Grenadier flash no longer breaks kill screens and meetings.\\r\\n- Dragging Viper / Rotting bodies no longer breaks Undertaker.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- Executioner Torment kills players again.\\r\\n- Jester Haunt kills players again.\\r\\n- Mercenary protection is removed upon their death.\\r\\n- Arsonist interactions contribute towards the douse limit.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Spectators that join without running **/spec** are no longer half-dead.\\r\\n- When Crewpostor replaces a real Impostor, the player being replaced gets a proper role.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Other Bugfixes**</summary>\\r\\n- Impostor replaced by a Crewpostor can no longer see their previous task text.\\r\\n- Camo Comms no longer shows other player names when revived.\\r\\n- Doors can be set to Skeld doors or be flat out removed properly on Submerged.\\r\\n- Private Chat is no longer broken.\\r\\n- Players disconnecting from the lobby no longer breaks the player count.\\r\\n- Disconnected players no longer leak their role color.\\r\\n- Submerged and Level Impostor no longer break when loading base game map assets.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes and Improvements**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\ndlekS tooltip in the Create Game Menu is legible now.\\r\\nImitator now shows (Imi) next to their name while imitating roles.\\r\\nZoom and Wiki buttons can be changed to be below or next to the Settings / Chat button.\\r\\nAmnesiac\'s Assassin configuration is improved.\\r\\nLobby view pane has been adjusted to be smaller.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- Assassin is now shown as a modifier, unless Double Shot is present, with a better wiki description.\\r\\n- Misguessing now shows who/what was attempted to be guessed in the end game summary [PR #173, DivanNL](https://github.com/AU-Avengers/TOU-Mira/pull/173).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- Keybind Actions are now available under the local settings, primarily for Android players.\\r\\n- The host can now run /kick and /ban mid-game [PR #170, VoidChaos](https://github.com/AU-Avengers/TOU-Mira/pull/170)\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-160","metadata":{"permalink":"/docs.toum.gg/blog/update-160","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-04-18-update-160.md","source":"@site/blog/first-release/2026-04-18-update-160.md","title":"v1.6.0 Update","description":"Town of Us: Mira has updated to v1.6.0!","date":"2026-04-18T00:00:00.000Z","tags":[],"readingTime":3.02,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-160","title":"v1.6.0 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"v1.6.1 Update","permalink":"/docs.toum.gg/blog/update-161"},"nextItem":{"title":"v1.5.9 Update","permalink":"/docs.toum.gg/blog/update-159"}},"content":"## Town of Us: Mira has updated to [v1.6.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.0)!\\r\\n\\r\\nThis update includes bug fixes and improvements from the previous version(s). As always, be sure to do a fresh install!\\r\\n\\r\\n**Note:** Before playing, you must reset your keybinds, otherwise your W key will be bound to the zoom key, and Puppeteer/Parasite will be broken, so on and so forth.\\r\\n\\r\\nSee changelog below for the full list of bug fixes, known bugs and changes/improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n**Known bugs with this update:**\\r\\n\\r\\n- Private chats are invisible to players killed mid-meeting.\\r\\n- Private chats for living players sometimes get deleted when a new public chat message is added.\\r\\n- Controlled players (via Parasite/Puppeteer) appear to be stuck in a walk cycle when they are walking onto a wall, showing they are under control.\\r\\n- Neutral Wildcard may duplicate the amount of each neutral present if any selected slots are wildcards.\\r\\n- Ghostwalkers are sometimes unable to use the Zipline, Platform, or Ladders.\\r\\n- When Haunter finishes their tasks, sometimes the Impostors will not get an arrow to the Haunter, essentially screwing them over.\\r\\n\\r\\n**Known Hide and Seek Bugs:**\\r\\n\\r\\n- The Seeker is missing animations for the hiders\\r\\n- Hiders ignore their vent uses\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n- Medic can no longer hand out shields again when settings forbid them.\\r\\n- Medic shields are destroyed properly if the setting is set.\\r\\n- Re-applying Magic Mirrors immediately no longer breaks.\\r\\n- Guardian Angel\'s protection is properly checked.\\r\\n- Engineer can no longer bypass Plumber\'s Barricades.\\r\\n- Operative and Sentry\'s Portable cameras are now functioning on Android.\\r\\n- Medium properly hides pets when anonymous players are enabled.\\r\\n- Monarch can properly knight regardless of the First Round Use setting.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n- Shapeshifter\'s name is properly changed.\\r\\n- Parasite victims properly die when the time runs out.\\r\\n- Hypnotist\'s Hysteria can no longer softlock the player upon death.\\r\\n- Warlock\'s Burst Kill works again.\\r\\n- Herbalist\'s herbs reset properly across rounds.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n- First-Round settings no longer interfere with Amnesiac\\r\\n- Fairy can no longer target Neutral Outliers.\\r\\n- Spectre can spook properly again.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n- Spectators who join without running /spec are no longer half-dead.\\r\\n- When Crewpostor replaces a real Impostor, the player being replaced gets a proper role.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n- Egotist and Crewpostor labels are shortened on player names.\\r\\n- The Wiki now allows searching by faction/alignment.\\r\\n- Disconnected players are kept properly displayed in the meeting and in the end-game summary.\\r\\n- Camo Comms, Mix-Up, and Vent System checks are far more optimized now, reducing lagspikes and general instability.\\r\\n- Plumber now has a Flush duration, blocking any vents in use for a set duration.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n- Current Region is now displayed in the lobby.\\r\\n- Trapper\'s feedback now includes Hyperlinks.\\r\\n- Many game settings are reorganized.\\r\\n- April Fools mode is temporarily removed from the main menu for the sake of stability.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n- Cleaned bodies can now be set to display as Missing, Disconnected, or Dead, applicable to Viper, Rotting, Chef, and Janitor.\\r\\n- Kill Animation background can now optionally be colored based on the killer\'s Faction or Role Color.\\r\\n- Added Role List Bucket tooltips while hovering (PR #156 by Maxi0fc)\\r\\n- Investigator footprints can now be set to be based on Distance or Time.\\r\\n- New Crewmate Killing role has been added: Officer.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-159","metadata":{"permalink":"/docs.toum.gg/blog/update-159","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-03-21-update-159.md","source":"@site/blog/first-release/2026-03-21-update-159.md","title":"v1.5.9 Update","description":"Town of Us: Mira has updated to v1.5.9!","date":"2026-03-21T00:00:00.000Z","tags":[],"readingTime":3.16,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-159","title":"v1.5.9 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"v1.6.0 Update","permalink":"/docs.toum.gg/blog/update-160"},"nextItem":{"title":"v1.5.4 Update","permalink":"/docs.toum.gg/blog/update-154"}},"content":"## Town of Us: Mira has updated to v1.5.9!\\r\\n\\r\\nThis update includes critical changes and bug fixes, and introduces a new role. As always, be sure to do a fresh install!\\r\\n\\r\\n**Known bugs with this update:**\\r\\n\\r\\n- Operative and Sentry Portable cameras are unusable on Android.\\r\\n- Some roles (such as Hunter) are known to have issues on Android, for reasons unknown to us.\\r\\n- Private chats are invisible to players killed mid-meeting.\\r\\n- Neutral Wildcard may duplicate the amount of each neutral present if any selected slots are wildcards.\\r\\n\\r\\nSee changelog below for full list of bug fixes, changes and improvements.\\r\\n\\r\\n---\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n## New Role \u2014 The [Herbalist](/docs/roles/impostor/power/herablist) (Impostor Power)\\r\\n\\r\\nThe Herbalist has many abilities tied to one cooldown, either to help Impostors or to affect what others see.\\r\\n\\r\\n**Herablist Abilities:**\\r\\n\\r\\n- **Expose:** Expose a player to all Impostors, revealing their role but preventing them from being guessed.\\r\\n- **Confuse:** Confuse a player with fungal spores to prevent them from identifying players.\\r\\n- **Protect:** Protect a player temporarily as if you were a Cleric, including other impostors.\\r\\n\\r\\n---\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role & Modifier Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Monarch\'s Round One setting is properly checked.\\r\\n* May be fixed: Medic Shield is no longer ignored if it is supposed to break.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Hypnotist no longer breaks Mix-Up or kill animations.\\r\\n* Ambusher is no longer caught by Investigator footprints.\\r\\n* Traitor is no longer unguessable if Crewpostor is disabled.\\r\\n* Players controlled by a Puppeteer can no longer no-clip when they\'re too close to the wall.\\r\\n* Grenadier\'s flash no longer prevents abilities from being used. (besides reports).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Amnesiac properly removes their \\"win condition\\" information from the task tab.\\r\\n* Doomsayer causes of death appear consistently now.\\r\\n* Spectre no longer prevents Neutral Evils from winning.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifiers**</summary>\\r\\n* Lovers can no longer chat when under control\\r\\n\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Ghostwalker roles spawn properly on Submerged\\r\\n* Players are no longer kicked out of vents that there were no longer present in.\\r\\n* Multi-kills from Bomber and Arsonist no longer break when one of the players is shielded\\r\\n* Negative rounds will no longer appear in the Game Summary.\\r\\n* Skeld decor settings are now checked properly.\\r\\n* dlekS will no longer cause the Create Game Menu to freeze.\\r\\n* \\"Airship\\" is no longer shown when \\"dlekS\\" is actually selected.\\r\\n* Better Skeld\'s Vent Network connects the Navigation vent to Weapons properly.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* More roles have role banners in the game options pane.\\r\\n* More role and modifier icons have been redrawn in a higher quality.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Main Changes**</summary>\\r\\n* [Medium](/docs/roles/crewmate/investigative/Medium) has been fully reworked.\\r\\n* The wiki now has a way to view game settings and includes a Terminology page.\\r\\n* Ghost roles are now in an Afterlife category rather than Crew Investigative or Neutral Evil.\\r\\n* Vanilla roles have their own colors now, and are fully integrated into the mod.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Critical Changes**</summary>\\r\\n* All Role List buckets are reset! The options are now unable to be affected by the addition of extra role buckets.\\r\\n* Kills are now confirmed by the host before they are visible for everyone else. This means that there are no more death desyncs.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Chat Changes**</summary>\\r\\n* When a player is kicked for missing a mod, the host is now properly notified.\\r\\n* Lobby Rules Messages are now titled \\"Lobby Rules\\" instead of \\"System\\".\\r\\n* Added /info command for roles with meeting info. ([PR #143](https://github.com/AU-Avengers/TOU-Mira/pull/142), idkimneil)\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-154","metadata":{"permalink":"/docs.toum.gg/blog/update-154","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-02-11-update-154.md","source":"@site/blog/first-release/2026-02-11-update-154.md","title":"v1.5.4 Update","description":"Town of Us: Mira has updated to v1.5.4!","date":"2026-02-11T00:00:00.000Z","tags":[],"readingTime":1.05,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-154","title":"v1.5.4 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.5.9 Update","permalink":"/docs.toum.gg/blog/update-159"},"nextItem":{"title":"v1.5.3 Update","permalink":"/docs.toum.gg/blog/update-153"}},"content":"## Town of Us: Mira has updated to [v1.5.4](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.5.4)!\\r\\n\\r\\nThis update includes bug fixes and improved map configurations! Be sure to do a fresh install.\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmate Roles**</summary>\\r\\n* Mirrorcaster no longer bypasses their cooldowns.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutral Roles**</summary>\\r\\n* Soul Collected bodies are now removed upon revival.\\r\\n</details></details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Fixes**</summary>\\r\\n* Deadly Quota\'s guess setting is checked correctly again.\\r\\n* Taskmaster no longer activates when the player is a Vampire/Traitor.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Deaths should no longer desync under race conditions with meetings.\\r\\n* Kills can no longer be triggered in the lobby from cheat clients.\\r\\n* Role icons will no longer appear behind text in the role tab.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Additions and Known Issues**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* Visual Theme toggles for Skeld, Mira, and Polus can now be adjusted.\\r\\n* Add Required Mods setting for hosts.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Known Issues**</summary>\\r\\n* Sentry\'s portable cameras are completely broken on Starlight.\\r\\n</details>\\r\\n</details>"},{"id":"update-153","metadata":{"permalink":"/docs.toum.gg/blog/update-153","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-02-09-update-153.md","source":"@site/blog/first-release/2026-02-09-update-153.md","title":"v1.5.3 Update","description":"Town of Us: Mira has updated to v1.5.3!","date":"2026-02-09T00:00:00.000Z","tags":[],"readingTime":1.97,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-153","title":"v1.5.3 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.5.4 Update","permalink":"/docs.toum.gg/blog/update-154"},"nextItem":{"title":"v1.5.2 Update","permalink":"/docs.toum.gg/blog/update-152"}},"content":"## Town of Us: Mira has updated to [v1.5.3](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.5.3)!\\r\\n\\r\\nThis update includes bug fixes and improved map configurations! Be sure to do a fresh install.\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmate Roles**</summary>\\r\\n* Veteran should no longer crash from trying to defend and retaliate against Pestilence.\\r\\n* Imitator should properly show the crewmate variants of roles.\\r\\n* Mystic can see the location of viper bodies properly now.\\r\\n* Sentry now shows up in Doomsayer hints.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutral Roles**</summary>\\r\\n* Arsonist should no longer break when igniting a shielded player.\\r\\n* Amneniac can no longer be its own Executioner/Fairy target, preventing game crashes.\\r\\n* Glitch Hack no longer breaks kills when triggered by a basic button press.\\r\\n* Pestilence announcement now works properly.\\r\\n* Spectre should no longer cause issues with win conditions.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n* URole changing mid animation no longer softlocks the player.\\r\\n* Player checks are cached, resulting in better performance.\\r\\n* Kill animations should no longer break from corrupted memory.\\r\\n* Kills should no longer desync.\\r\\n* Pseudo-spectators should no longer appear in meetings.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes, Improvements and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n#### For Developers:\\r\\n* The Player Reveal system has been changed a bit. Use BaseRevealModifier instead!\\r\\n* MeetingMenu abilities can now have text, but this is optional for mod developers.\\r\\n#### Other Changes:\\r\\n* Medium is no longer a Support role, and is now an Investigative role.\\r\\n* Rotting now has the base game Viper animation (and isn\'t removed from the player list).\\r\\n* Neutrals and Egotist now have a grey map.\\r\\n* Impostors and Crewpostor always have a red map now.\\r\\n* Some game options have moved into the Game Mechanics category.\\r\\n* The mod now displays a new smooth splash screen.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Meeting abilities now have text that can be translated.\\r\\n* The Eiki now shows colors based on alignment rather than actual role color.\\r\\n* Alliance modifiers now display a notification explaining the player\'s objective.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* Veteran can now be told if an attack was attempted on them in the meeting (Optional).\\r\\n* Amnesiac by default picks up faction modifiers.\\r\\n* All neutrals have objective text in their task list, just like Impostors.\\r\\n</details>\\r\\n</details>"},{"id":"update-152","metadata":{"permalink":"/docs.toum.gg/blog/update-152","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-01-19-update-152.md","source":"@site/blog/first-release/2026-01-19-update-152.md","title":"v1.5.2 Update","description":"Town of Us: Mira has updated to v1.5.2!","date":"2026-01-19T00:00:00.000Z","tags":[],"readingTime":1.32,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-152","title":"v1.5.2 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.5.3 Update","permalink":"/docs.toum.gg/blog/update-153"},"nextItem":{"title":"v1.5.0 Update","permalink":"/docs.toum.gg/blog/update-150"}},"content":"## Town of Us: Mira has updated to [v1.5.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.5.2)!\\r\\n\\r\\nThis update includes bug fixes and improved map configurations. Be sure to do a fresh install!\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Ghost Roles**</summary>\\r\\n* Spectre\'s role tab now displays the information properly.\\r\\n* Ghostwalker roles should appear to spawn properly for all players.\\r\\n* Spectator should no longer error out in the meeting.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n* Upper and Lower Deck are no longer broken visually on Submerged ([PR #117](https://github.com/AU-Avengers/TOU-Mira/pull/117), jukixyo).\\r\\n* Cooldown Pause in Panels option is no longer duplicated in the settings menu.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes, Improvements and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* The Main Menu now displays the Discord Server and Source Code links next to the Fools Mode toggle.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Specific Better Maps settings can be changed Per-Map or via one setting.\\r\\n* Camo Comms can be toggled for each map now.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\nArsonist Option: Douses Possible at Once.\\r\\n* Vanilla Tweak Option: Ghostwalkers can Fix Sabotages Toggle.\\r\\n* Host Option: Multiplayer Freeplay Mode.\\r\\n* Better Maps Options: Tasks to use Admin/Cams/Doorlogs/Vitals.\\r\\n* Better Skeld Option: Quad-Group Vent System Toggle.\\r\\n* Better Fungle Options: No Ladder Cooldown toggle.\\r\\n* Better Submerged Options: Reactor/Oxygen Duration Changes.\\r\\n* Better LI Options: Reactor/Oxygen/Mix-Up Duration Changes, No Ladder Cooldown Toggle.\\r\\n</details>\\r\\n</details>"},{"id":"update-150","metadata":{"permalink":"/docs.toum.gg/blog/update-150","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2026-01-04-update-105.md","source":"@site/blog/first-release/2026-01-04-update-105.md","title":"v1.5.0 Update","description":"Town of Us: Mira has updated to v1.5.0!","date":"2026-01-04T00:00:00.000Z","tags":[],"readingTime":3.11,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-150","title":"v1.5.0 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.5.2 Update","permalink":"/docs.toum.gg/blog/update-152"},"nextItem":{"title":"v1.4.1 Update","permalink":"/docs.toum.gg/blog/update-141"}},"content":"## Town of Us: Mira has updated to [v1.5.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.5.0)!\\r\\n\\r\\n#### This version runs on the latest version of Among Us. A fresh install is recommended to ensure no conflicts with old files!\\r\\n\\r\\nThis update introduces 5 new roles and 2 new Impostor modifiers!\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## New Roles!\\r\\n\\r\\n### The [Monarch](/docs/roles/crewmate/power/monarch) (Crewmate Power)\\r\\n\\r\\nThe **Monarch** can knight other players, giving them additional votes.\\r\\n\\r\\n### The [Sentry](/docs/roles/crewmate/support/sentry) (Crewmate Support)\\r\\n\\r\\nThe **Sentry** can place additional cameras across the map, which can then be viewed from Security or by players with portable cameras.\\r\\n\\r\\n### The [Time Lord](/docs/roles/crewmate/power/time%20lord) (Crewmate Power)\\r\\n\\r\\nThe **Time Lord** can rewind time, forcing players to retrace their path and potentially reviving fallen players!\\r\\n\\r\\n### The [Parasite](/docs/roles/impostor/killing/parasite) (Impostor Powwer)\\r\\n\\r\\nThe **Parasite** can overtake a nearby player and temporarily control their movement before killing them.\\r\\n\\r\\n### The [Puppeteer](/docs/roles/impostor/power/puppeteer) (Impostor Power)\\r\\n\\r\\nThe **Puppeteer** can control other players and force them to kill someone else.\\r\\n\\r\\n---\\r\\n\\r\\n## New Modifiers!\\r\\n\\r\\n### Circumvent (Impostor Passive)\\r\\n\\r\\nYou lose the ability to vent around the map.\\r\\n\\r\\n### Deadly Quota (Impostor Passive)\\r\\n\\r\\nYou must meet your kill quota or lose the game, even if fellow Impostors win.\\r\\n\\r\\n---\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Prosecutor\'s use is no longer wasted when their selection dies mid-meeting.\\r\\n* Jailor uses are no longer removed 2 times in a row.\\r\\n* Veteran no longer loses instantly in a 1v1 when on their last alert.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Traitor can be guessed properly again.\\r\\n* Undertaker\'s Drag/Drop button no longer locks up after consecutive games.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Amnesiac, Executioner and Fairy will see their target properly.\\r\\n* Doomsayer guesses now appear properly instead of appearing as kills.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Fixes**</summary>\\r\\n* Crewpostor is treated as a regular Impostor and no longer loses when only Crewmates remain.\\r\\n* Disperse no longer breaks on Ladders or Platforms.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* First round death indicator no longer exposes morphed players.\\r\\n* Vanilla roles are now properly clickable in chats to open their wiki entries.\\r\\n* Epic Games can use Practice mode again.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes, Improvements and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* The private chatboxes are no longer toggled via separate buttons, but rather within the chat itself.\\r\\n* Local Settings have been split up into two tabs, and the button slider has moved under MiraAPI Settings.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Morphing into a player with the First Death Shield will show a fake shield.\\r\\n* Guesser Menu now allows you to search for roles and modifiers for ease of use.\\r\\n* Most cooldowns can now go from 5 seconds all the way to 2 minutes.\\r\\n* Options for Sheriff, Vampire, Oracle, and Vigilante are compressed within the wiki.\\r\\n* New artwork has been added, and some old artwork has been cleaned up.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* Better Airship Option: No Ladder Cooldown.\\r\\n* Mystic Option: Show Death Pop-Up.\\r\\n* Arsonist Option: Impostor Vision. (Parity Change from TOUR)\\r\\n* Altruist Option: Kill on Revive Start.\\r\\n* Grenadier Option: Flash During Sabotage. (Parity Change from TOUR)\\r\\n* Host-Only Option: Toggle Lobby No-Clip.\\r\\n* New Impostor Roles: Parasite and Puppeteer.\\r\\n* New Crewmate Roles: Monarch, Sentry, and Time Lord.\\r\\n* New Impostor Modifiers: Circumvent and Deadly Quota.\\r\\n* Hosts can now add a \\"LobbyRules.txt\\" file next to the mod to show their houserules in-game ([PR #108](https://github.com/AU-Avengers/TOU-Mira/pull/108), Neil).\\r\\n</details>\\r\\n</details>"},{"id":"update-141","metadata":{"permalink":"/docs.toum.gg/blog/update-141","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-12-14-update-141.md","source":"@site/blog/first-release/2025-12-14-update-141.md","title":"v1.4.1 Update","description":"Town of Us: Mira has updated to v1.4.0!","date":"2025-12-14T00:00:00.000Z","tags":[],"readingTime":2.4,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-141","title":"v1.4.1 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.5.0 Update","permalink":"/docs.toum.gg/blog/update-150"},"nextItem":{"title":"v1.4.0 Update","permalink":"/docs.toum.gg/blog/update-140"}},"content":"## Town of Us: Mira has updated to [v1.4.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.4.0)!\\r\\n\\r\\nThis update includes fixes for some critical bugs that were introduced in v1.4.0. There are also additional changes to settings, so be sure to check out the changelog!\\r\\n\\r\\nThis update also includes a download specifically for macOS and Linux users. Please be sure to do a fresh install.\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Jailor no longer shows a kill screen upon execution.\\r\\n* Seer no longer gains additional uses from unfinished player comparisons.\\r\\n* Imitator can no longer become basic Impostor or Survivor.\\r\\n* Vanilla Detective notes can be properly used in meetings ([PR #99](https://github.com/AU-Avengers/TOU-Mira/pull/99), Rewalo).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Fixed Eclipsal option name.\\r\\n* Traitor can no longer spawn like a basic Impostor role.\\r\\n* Double Undertakers can no longer grab the same body.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Spectre now spawns consistently\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Gamemode Fixes**</summary>\\r\\n* Hide and Seek modifiers no longer appear in guessing menus.\\r\\n* Classic Mode roles and modifiers can no longer spawn in Hide and Seek.\\r\\n* All game keybinds are moved to the right-hand side, no longer blocking vent uses in Hide and Seek.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Neutral Wildcard will no longer cause incorrect neutral role spawns.\\r\\n* April Fools bugs no longer appear when joining a lobby.\\r\\n* Fixed keybinds bypassing button checks from shields. \\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes, Improvements and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* All intro blurbs have been improved and simplified.\\r\\n* Crewpostor can no longer be a Jailor, Politician, Snitch, or Swapper.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Cached roles (such as Imitator or Traitor) will be displayed at the top of the Wiki.\\r\\n* Stricter anticheat improvements ([PR #96](https://github.com/AU-Avengers/TOU-Mira/pull/96), Rewalo).\\r\\n* Chat messages can now include most Unicode characters and can be up to 300 characters long ([PR #95](https://github.com/AU-Avengers/TOU-Mira/pull/95), Rewalo).\\r\\n* The chat now displays secondary text bubbles for Lover, Jailor, Impostor, and Vampire chat.\\r\\n* Lover chat is now a pink tint to make it stand out.\\r\\n* Hunter has configurable task options.\\r\\n* Engineer now has very configurable Vent, Fix, and Task settings.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* New Local Settings: Grenadier Flash Color & End Game Summary Message style.\\r\\n* Better Polus Setting: Move Bathroom vent to Medbay.\\r\\n* Better Mira HQ Setting: Better Vent Network.\\r\\n* New Keybinds added for zooming in and out.\\r\\n* New option: First Round Death Indicator.\\r\\n* New command: **/roles** ([PR #95](https://github.com/AU-Avengers/TOU-Mira/pull/95), Rewalo).\\r\\n* New Hide and Seek Modifier: Transporter.\\r\\n</details>\\r\\n</details>"},{"id":"update-140","metadata":{"permalink":"/docs.toum.gg/blog/update-140","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-11-27-update-140.md","source":"@site/blog/first-release/2025-11-27-update-140.md","title":"v1.4.0 Update","description":"Town of Us: Mira has updated to v1.4.0!","date":"2025-11-27T00:00:00.000Z","tags":[],"readingTime":3.72,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-140","title":"v1.4.0 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.4.1 Update","permalink":"/docs.toum.gg/blog/update-141"},"nextItem":{"title":"v1.3.0 Update","permalink":"/docs.toum.gg/blog/update-130"}},"content":"## Town of Us: Mira has updated to [v1.4.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.4.0)!\\r\\n\\r\\nThis version is compatible with the latest Among Us version (v.17.1.0). Please be sure to do a fresh install.\\r\\n\\r\\nThis update includes:\\r\\n\\r\\n- Modded Hide and Seek!\\r\\n- A new alliance modifier \u2014 Crewpostor!\\r\\n- Role reworks for Seer, Altruist and Egotist!\\r\\n- New cosmetics!\\r\\n\\r\\nSee changelog below for bugfixes, changes and improvements.\\r\\n\\r\\n- **Note:** Offline Practice Mode does **not** work for Epic Games at this time.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Hunter will no longer get their retribution on their last vote when Prosecuted.\\r\\n* Politician checks now round up rather than round down.\\r\\n* Mayor reveal no longer loops when opening the guess menu or wiki.\\r\\n* Mirrorcaster\'s attack information is now displayed properly.\\r\\n* Oracle now has Neutral Outlier Settings.\\r\\n* Lookout can no longer see basic Impostor/Crewmate Ghosts interact with their target.\\r\\n* Seer checks neutral outliers properly.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Ambusher animation loads properly for all players.\\r\\n* Spellslinger is no longer outed in the meeting.\\r\\n* Miner vents in Submerged now use the regular vent type rather than the pipe vent.\\r\\n* Traitor no longer spawns without cooldowns.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Amnesiac!Politician can campaign properly.\\r\\n* Survivor no longer survives death from scatter with their vest.\\r\\n* Werewolf cooldown is no longer locked to 5 seconds.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Fixed the lack of Neutral Outliers causing Wildcard Role buckets to spawn basic Crewmates.\\r\\n* Screen Flashes (from the likes of Medic, Warden, etc) now work during sabotages.\\r\\n* When going from a build that has Level Impostor or Submerged to one without them, the host menu will no longer softlock the game.\\r\\n* Any players who become Phantom will no longer hide their kill counters in the end-game summary.\\r\\n* Dummies in Freeplay/Practice Mode will always get a role without erroring out.\\r\\n* Submerged finally works on ToU: Mira and no longer breaks cooldowns.\\r\\n* Game End Timer no longer instantly ends the game if the previous match ended from time running out.\\r\\n* Buttons can no longer have negative cooldowns.\\r\\n* It is no longer possible to have multiple button modifiers with the same keybind.\\r\\n* Skeld doors on other maps work again.\\r\\n* Discord Rich Presence shows mod count properly.\\r\\n* Vanilla roles are properly displayed alongside other ToU roles.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes, Improvements and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* Base game Engineer can no longer be used in ToU Mira.\\r\\n* ToU Detective, Tracker, Guardian Angel, and Phantom have been renamed to Forensic, Sonar, Fairy, and Spectre.\\r\\n* Vanilla Viper has been moved into the Impostor Killing alignment.\\r\\n* Altruist by default sacrifices themselves when reviving, and can be changed to be like old Altruist or even older Altruist.\\r\\n* Egotist now speeds up players and lowers cooldowns the longer they stay alive, which is configurable.\\r\\n* Mercenary will protect players from attacks and gain double the profit by default.\\r\\n* Seer has been reworked into its Town of Salem counterpart, comparing two separate players. (Not finalized)\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Kill buttons and vent buttons are now organized in such a way to match vanilla and TOUR, respectively.\\r\\n* All maps now have offsets for Short Tasks, Long Tasks, and Cooldowns under the Better Map options.\\r\\n* Vanilla Viper now has the cause of death \\"Disintegrated\\".\\r\\n* Celebrity death message is now formatted as a list.\\r\\n* Dying to Submerged Oxygen now shows \\"Suffocated\\" as the cause of death.\\r\\n* Mayor sees all players they campaigned after reveal.\\r\\n* Freeplay now has three buttons available for enhanced testing.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* It is now possible to switch between Vanilla role assignment, Role List, and Min/Max Neutral List.\\r\\n* Modded Hide and Seek is now possible!\\r\\n* New Vanilla Tweak Options: Walk to Medscan Toggle, Hidden Pets, Removal Of Pets Upon Body Cleanse\\r\\n* New Alliance Modifier: Crewpostor! A Crewpostor is a crewmate that works solely for the Impostors, and becomes Traitor upon their deaths.\\r\\n* New options were added for independent configuration of dead players.\\r\\n* New options for Camouflage Comms: Camouflage Kill Screens in Comms, Hide Player Size, and Hide Player Speed.\\r\\n* New option for All Maps: Specified Door Types, including No Doors and Random Doors\\r\\n* Added dlekS into the randomized map list and in the game settings window.\\r\\n* Nearly all sabotage countdowns are now configurable.\\r\\n</details>\\r\\n</details>"},{"id":"update-130","metadata":{"permalink":"/docs.toum.gg/blog/update-130","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-10-14-update-130.md","source":"@site/blog/first-release/2025-10-14-update-130.md","title":"v1.3.0 Update","description":"Town of Us: Mira has updated to v1.3.0!","date":"2025-10-14T00:00:00.000Z","tags":[],"readingTime":2.74,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-130","title":"v1.3.0 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.4.0 Update","permalink":"/docs.toum.gg/blog/update-140"},"nextItem":{"title":"v1.2.1 Update","permalink":"/docs.toum.gg/blog/update-121"}},"content":"## Town of Us: Mira has updated to [v1.3.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.3.0)!\\r\\n\\r\\nThis version is **NOT** compatible with the latest Among Us version. Please refer to installation guides for how to downgrade your platform.\\r\\n\\r\\n---\\r\\n\\r\\nThis update introduces **2 new roles** and updates to the Neutral buckets!\\r\\n\\r\\nSee changelog below for bugfixes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### New Impostor Power Role \u2014 The Spellslinger!\\r\\n\\r\\nThe **Spellslinger** hexes players and releases a Hex Bomb! Crew must eliminate the Spellslinger or race to complete tasks before the hex clock runs out...\\r\\n\\r\\n### New Neutral Outlier Role \u2014 The Chef!\\r\\n\\r\\nThe **Chef** cooks dead bodies and must feed them to others to fulfill their quota to leave in victory!\\r\\n\\r\\n---\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Vigilante no longer wastes a use while guessing.\\r\\n* If a Prosecutor is punished and dies as a Celebrity, their death is no longer displayed.\\r\\n* Jailor no longer errors out from certain kills.\\r\\n* Hunter Retribution should appear for all clients properly now.\\r\\n* Medic will no longer trigger the shield if the kill button isn\'t usable.\\r\\n* Mirrorcaster will no longer trigger the mirror if the kill button isn\'t usable.\\r\\n* When an Amnesiac/Imitator becomes Snitch, their progress automatically updates.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Blackmailed victims are prevented from voting correctly.\\r\\n* Undertaker properly drops dead bodies.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* If an Executioner\'s target becomes a Vampire, they will no longer be able to end the game, but will still win.\\r\\n* Mercenary can no longer become Phantom if they bribed a player or had their role taken by an Amnesiac.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Aftermath will now properly trigger abilities as intended.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Wiki appears in front of all UI elements\\r\\n* First Round Shield will no longer trigger if the kill button isn\'t usable.\\r\\n* FFA Impostor Mode now hides impostor names from the chat.\\r\\n* Guess counts should no longer be counted in the main kill counter for the summary.\\r\\n* Haunter and Phantom no longer appear camouflaged during comms.\\r\\n* When a player disconnects, anyone who voted for them should no longer be stuck without a vote.\\r\\n* Client-side murders should no longer be an issue.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Changes and Additions**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* Mirrorcaster now has four types of information it can display based on the attack.\\r\\n* Inquisitor is no longer a Neutral Evil, but rather a Neutral Outlier alongside the new neutral role.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions**</summary>\\r\\n* Toggle Spectators options is under General Options.\\r\\n* Inquisitor Vanquish Round One toggle has been added\\r\\n* Rich Presence on Discord now shows the mod icon.\\r\\n* New Neutral Buckets: Neutral Wildcard (Non-Killing Neutrals) and Neutral Special (Neutral Killing and Outlier)\\r\\n* **New Neutral Outlier Role: The Chef!**\\r\\n  This role takes the dead bodies of players and feeds them to others, which all fulfills their quota to leave in victory!\\r\\n* **New Impostor Power Role: The Spellslinger!**\\r\\n  This role hexes players to then set off a hex bomb, in which the crew will need to get rid of the Spellslinger or finish their tasks against the hex clock.\\r\\n</details>\\r\\n</details>"},{"id":"update-121","metadata":{"permalink":"/docs.toum.gg/blog/update-121","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-09-28-update-121.md","source":"@site/blog/first-release/2025-09-28-update-121.md","title":"v1.2.1 Update","description":"Town of Us: Mira has updated to v1.2.1!","date":"2025-09-28T00:00:00.000Z","tags":[],"readingTime":0.83,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-121","title":"v1.2.1 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.3.0 Update","permalink":"/docs.toum.gg/blog/update-130"},"nextItem":{"title":"v1.2.0 Update","permalink":"/docs.toum.gg/blog/update-120"}},"content":"## Town of Us: Mira has updated to [v1.2.1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.2.0)!\\r\\n\\r\\nSee changelog below for bugfixes and improvements.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Localisation Updates**</summary>\\r\\n* Impostor Abilities are nearly fully ready for translations.\\r\\n* Doomsayer now adds localization changes correctly.\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Other Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Wiki Bugfixes**</summary>\\r\\n* Fixed Wiki entries for Diseased, Lovers, Bait, Mini, Rotting, Satellite, Amnesiac, and Plumber.\\r\\n* Vanilla wiki entries get properly localized to your active language.\\r\\n* Inquisitor Report entries can now be clicked to open their wiki entries.\\r\\n* Vanilla Wiki entries for Viper and Detective no longer appear as \\"STRMISS\\"\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Misc. Bugfixes**</summary>\\r\\n* Fixed Wiki entries for Diseased, Lovers, Bait, Mini, Rotting, Satellite, Amnesiac, and Plumber.\\r\\n* Vanilla wiki entries get properly localized to your active language.\\r\\n* Inquisitor Report entries can now be clicked to open their wiki entries.\\r\\n* Vanilla Wiki entries for Viper and Detective no longer appear as \\"STRMISS\\"\\r\\n</details>\\r\\n</details>"},{"id":"update-120","metadata":{"permalink":"/docs.toum.gg/blog/update-120","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-09-24-update-120.md","source":"@site/blog/first-release/2025-09-24-update-120.md","title":"v1.2.0 Update","description":"Town of Us: Mira has updated to v1.2.0!","date":"2025-09-24T00:00:00.000Z","tags":[],"readingTime":2.93,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-120","title":"v1.2.0 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.2.1 Update","permalink":"/docs.toum.gg/blog/update-121"},"nextItem":{"title":"v1.1.1 Update","permalink":"/docs.toum.gg/blog/update-111"}},"content":"## Town of Us: Mira has updated to [v1.2.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.2.0)!\\r\\nThis update is compatible with the latest Among Us version (v17.0.0). Please be sure to update your base game before installing.\\r\\n\\r\\nSee changelog below for bugfixes and improvements.\\r\\n\\r\\n<sub>**Note:** The Epic Games crash issues have largely been resolved with this update. If you experience crashes or failure to launch, please make a **Mira Bug Ticket** ticket in the [TOU Support](https://discord.com/channels/890249154402586734/900986905154453504) Discord server and provide your LogOutput & ErrorLogs (found in the BepInEx folder) and your system operating information.</sub>\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* If the Lookout disconnects or gets converted, their feedback will no longer be shown to others in the chat.\\r\\n* Snitch is revealed properly to the Traitor as intended.\\r\\n* Traitor will always see the Snitch regardless of settings, but Snitch can only see Traitor based on specific settings.\\r\\n* Tracker and Engineer get task uses properly.\\r\\n* Mirrorcaster can no longer Unleash onto the player that they protect at the same time.\\r\\n* The Sheriff can kill the Ambassador without misfiring (bad checks).\\r\\n* The Prosecutor button is no longer hidden when the skip button is hidden.\\r\\n* Jailee is no longer in Jail if the Jailor is converted.\\r\\n* The Mayor no longer trips up Traitor checks from sending repetitive requests to all players.\\r\\n* Fixing Comms as the Engineer no longer uses up two charges.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Traitor can no longer vent as a ghost.\\r\\n* Hypnotist applies the same body type to all players, and clears properly without breaking.\\r\\n* Swooper player names are no longer revealed during Camo Comms.\\r\\n* Morphling player names are no longer revealed during Camo Comms after unmorphing.\\r\\n* Ambusher can no longer get outed when they are taking bodies away.\\r\\n* When the Ambusher\'s victim is revived while their body is taken away, the ambusher will no longer softlock.\\r\\n* Miner vents are fully disabled from other roles if they aren\'t visible.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Amnesiac Inquisitor can no longer target themselves.\\r\\n* Phantom, Executioner, and Jester ghost kills are now run through a more direct method to force a murder at all costs.\\r\\n* Glitch player names are no longer revealed during Camo Comms after un-mimicking.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Celebrity Report no longer gets parsed incorrectly.\\r\\n* When Spooked by a Phantom, the Celebrity shows their cause of death as Spooked properly.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Haunter, Phantom, and Snitch now ignore Sabotage and Non-Task Information on the task list.\\r\\n* There are now checks to prevent votes on dead players or votes happening from dead players.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Chat Tags now italicize on hover. (PR [#65](https://github.com/AU-Avengers/TOU-Mira/pull/65), Chipseq)\\r\\n* Controllers on the Main Menu can now select the April Fools Toggle.\\r\\n* Chat is now hidden from recently killed players.\\r\\n* Your abilities can no longer be triggered when typing in lovers chat.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Changes**</summary>\\r\\n* Nearly complete Chinese translations, as well as partial translations for Dutch, French, German, Russian, and Spanish.\\r\\n* Players can now spectate in games by running \\"/spec\\" in their chat.\\r\\n* It is now possible to change what ranges of buttons are affected by the starting cooldown, if any.\\r\\n</details>\\r\\n\\r\\n</details>"},{"id":"update-111","metadata":{"permalink":"/docs.toum.gg/blog/update-111","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-08-23-update-111.md","source":"@site/blog/first-release/2025-08-23-update-111.md","title":"v1.1.1 Update","description":"Town of Us: Mira has updated to v1.1.1!","date":"2025-08-23T00:00:00.000Z","tags":[],"readingTime":2.88,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-111","title":"v1.1.1 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.2.0 Update","permalink":"/docs.toum.gg/blog/update-120"},"nextItem":{"title":"v1.1.0 Update","permalink":"/docs.toum.gg/blog/update-110"}},"content":"## Town of Us: Mira has updated to [v1.1.1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.1.1)!\\r\\n<sub>**Note:** Some Epic Games users may experience crashes or failure to launch due to a change in the base game version. \\r\\nThis is unrelated to the mod, but the dev team is aware and trying to find a solution. </sub>\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Detective no longer throws null errors, which broke ghost roles in the process.\\r\\n* Blessed guessers no longer stay alive from misguessing.\\r\\n* Haunter calculations actually work properly.\\r\\n* Transporter can no longer throw players out of bounds, again. ([PR #55](https://github.com/AU-Avengers/TOU-Mira/pull/55), Nix-main).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Ambusher cannot drop bodies into the wall anymore ([PR #53](https://github.com/AU-Avengers/TOU-Mira/pull/53), Nix-main).\\r\\n* Ambusher and Scavenger Arrows are removed correctly when a meeting starts.\\r\\n* Ambusher has extra checks to remove the animation when a meeting starts or if the ambusher is killed mid-ambush.\\r\\n* Ambassador may only retrain themselves in FFA Impostor Mode now.\\r\\n* Solo killing settings for Blackmailer and Undertaker now work correctly.\\r\\n* Dragging a body between vents as Undertaker is now instant.\\r\\n* If the Swooper has limited uses, then they cannot go under 0 uses.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Extra checks are added with Haunt/Torment/Spook menus to not linger around and allow double kills.\\r\\n* Jester no longer overrides their cause of death when Prosecuted.\\r\\n</details> \\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Lover death checks are run on the dead lover\'s end instead of everyone else\'s end, fixing lovers not dying together properly.\\r\\n* Telepath cannot spawn with FFA Impostor Mode anymore.\\r\\n* When the Prosecutor fails and dies, they will not announce their death if they\'re a Celebrity.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Target assignment is now done in a specific order, so ego exe targets, ego traitor, exe with lover target should no longer be possible.\\r\\n* The In-Game Wiki shows Pestilence and Mayor entries properly again.\\r\\n* The Guess Menu checks for role chance AND amount correctly.\\r\\n* If Executioner and Guardian Angel turn into disabled roles on target death, then said roles can be guessed.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* The subtitle for the Win Screen with nobody winning is now renamed to \\"Game Draw!\\" instead of \\"Nobody Wins!\\" as Neutral Evils can still win.\\r\\n* Main Menu has been slightly adjusted visually; the major change is the April Fools Selector now being moved into the main UI.\\r\\n* Redundant April Fools check was removed. ([PR #57](https://github.com/AU-Avengers/TOU-Mira/pull/57), Astral).\\r\\n* Added chat tags for roles and modifiers by doing #soul-collector or &celebrity, for example. ([PR #58](https://github.com/AU-Avengers/TOU-Mira/pull/58), Chipseq).\\r\\n* Keybinds are far more responsive now.\\r\\n* Doomsayer report shows vanilla roles/non-TOU roles under an outsider category.\\r\\n* Doomsayer report shows clickable wiki entries for role reports.\\r\\n* Celebrity message shows a clickable Wiki entry for their killer\'s role.\\r\\n* Camo Comms should no longer be prone to crashing.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions and Changes**</summary>\\r\\n* **Added:** Bomb Round One Option has been added for Bomber. ([PR #54](https://github.com/AU-Avengers/TOU-Mira/pull/54), Nix-main).\\r\\n</details>\\r\\n</details>"},{"id":"update-110","metadata":{"permalink":"/docs.toum.gg/blog/update-110","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-08-03-update-110.md","source":"@site/blog/first-release/2025-08-03-update-110.md","title":"v1.1.0 Update","description":"Town of Us: Mira has updated to v1.1.0!","date":"2025-08-03T00:00:00.000Z","tags":[],"readingTime":3.61,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-110","title":"v1.1.0 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.1.1 Update","permalink":"/docs.toum.gg/blog/update-111"},"nextItem":{"title":"v1.0.5 Update","permalink":"/docs.toum.gg/blog/update-105"}},"content":"## Town of Us: Mira has updated to [v1.1.0](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.1.0)!\\r\\n<sub>**Note:** Some Epic Games users may experience crashes or failure to launch due to a change in the base game version. The dev team is aware of this issue, though it is unrelated to the mod itself.</sub>\\r\\n\\r\\n### New Crewmate Protective Role \u2014 The [Mirrorcaster](/docs/roles/crewmate/protective/mirrorcaster)!\\r\\nThe **Mirrorcaster** can place a protective Magic Mirror on another player to absorb attacks, which they can unleash onto another player.\\r\\n\\r\\n### New Impostor Power Role \u2014 The [Ambassador](/docs/roles/impostor/power/ambassador)!\\r\\nThe **Ambassador** can retain themselves or impostor teammates into other roles, under certain conditions. (Note: the confirmation option is not currently functional. This role also does not play correctly with FFA Impostor mod currently).\\r\\n\\r\\n### New Impostor Killing Role \u2014 The [Ambusher](/docs/roles/impostor/killing/ambusher)!\\r\\nThe **Ambusher** can pursue a player and use them to kill the closest person to them. If successful, the Ambusher will become a shadow and teleport the body back to themselves.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Imitator checks should no longer prevent them from selecting a new role.\\r\\n* Warden will add a second to the cooldown of whatever ability is used on a fortified player to prevent brute force attempts.\\r\\n* Lookout can see the roles that interacted with their dead targets again.\\r\\n* Prosecutor uses are used correctly and no longer force a prosecution twice in a row.\\r\\n* Veteran will properly add alert uses via tasks to prevent ending the game.\\r\\n* The Mayor reveal is now visually correct and shows the hands correctly.\\r\\n* Medic Shield, Cleric Barrier, and Warden Fort will be removed on disconnection properly.\\r\\n* Detective / Medic report options being at 0 seconds will no longer stop any information.\\r\\n* Transporter now transports players correctly, no more desync.\\r\\n* If the Snitch reveals neutral killers, they now show the role color.\\r\\n* If a blessed player is swapped, the swapped target will still be ejected.\\r\\n* Transporting a body next to a wall no longer places it outside of bounds ([PR #51](https://github.com/AU-Avengers/TOU-Mira/pull/51), Nix-main).\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* If an Undertaker dies while dragging a body, the body will be let go automatically.\\r\\n* Abilities can be used in Eclipse and while flashed now (bodies are not reportable in grenade flash, though, only in Eclipse).\\r\\n* Scavenger targets are no longer given during a meeting.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Fix Alive Neutral Ghost on Jester win.\\r\\n* Jester Haunt, Phantom Spook, and Executioner Torment ignore shields correctly now.\\r\\n* Jester Haunt, Phantom Spook, and Executioner Torment cannot be opened multiple times anymore.\\r\\n* Amnesiac will correctly know who their target is as GA or Executioner.\\r\\n* Amnesiac will remove douses/infection when picking up Arsonist/Plaguebearer.\\r\\n* Pestilence transform checks will run locally for the Plaguebearer, not everyone in general, to avoid desync or anything of that degree.\\r\\n* Amnesiac will no longer become an OG Vampire unless they took the role of the OG Vamp.\\r\\n</details> \\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Shy ghosts are no longer invisible, but their hat stays translucent.\\r\\n* Mini and Giant can climb ladders correctly now without getting stuck.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Zipline and Ladder work for Phantom/Haunter once again.\\r\\n* Impostor Streak Reduction no longer triggers the 1 impostor bug.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Dying to Veteran now says \\"Attacked\\", dying to Deputy says \\"Blasted\\", and dying to Vampire says \\"Bitten\\".\\r\\n* Support for other MiraAPI mods has been improved across the board (this does not affect you if you only play Town of Us Mira standalone).\\r\\n* Plumber now swaps between 3 barricade sprites.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions and Changes**</summary>\\r\\n* **Added:** New Role Buckets: Impostor Power and Impostor Special.\\r\\n* **Added:** Added a Maximum Medic Shield Uses setting.\\r\\n* **Added:** Game Timer can now be paused at certain times within meetings.\\r\\n* **Changed:** Torch is no longer immune to Eclipsal.\\r\\n* **Changed:** Mercenary and GA can win with their targets from alliance modifiers.\\r\\n* **Changed:** Plumber barricades will now only stay for a set amount of rounds (customizable, can be infinite).\\r\\n</details>\\r\\n\\r\\n</details>"},{"id":"update-105","metadata":{"permalink":"/docs.toum.gg/blog/update-105","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-07-19-update-105.md","source":"@site/blog/first-release/2025-07-19-update-105.md","title":"v1.0.5 Update","description":"Town of Us: Mira has updated to v1.0.5!","date":"2025-07-19T00:00:00.000Z","tags":[],"readingTime":3.96,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-105","title":"v1.0.5 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.1.0 Update","permalink":"/docs.toum.gg/blog/update-110"},"nextItem":{"title":"v1.0.2 Update","permalink":"/docs.toum.gg/blog/update-102"}},"content":"## Town of Us: Mira has updated to [v1.0.5](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.0.5)!\\r\\n<sub> **Note:** Some Epic Games users may experience crashes or failure to launch due to a change in the base game version. The dev team is aware of this issue, but there is no solution at this time. </sub>\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>Role Bugfixes</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Rainbow Tracker arrows will be rainbow instead of black.\\r\\n* The Mayor is no longer able to become Traitor.\\r\\n* Prosecutor no longer ends meetings instantly.\\r\\n* Oracle Blessing stops the assassin from guessing.\\r\\n* Footprint intervals are now in time, not distance.\\r\\n* Footprints are layered correctly.\\r\\n* If specified, trapper uses are reset properly after each round.\\r\\n* If the \\"Jailee Can Use Public Chat\\" option is disabled, the Jailee can speak properly in the private chatbox.\\r\\n* If a Deputy camps a player in a 1v2, and the camped player dies, the Deputy continues the game correctly.\\r\\n* Deputies no longer hold onto the killer information from the previous round.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* The Hypnotist can no longer hypnotize once Mass Hysteria is in action.\\r\\n* If the Hypnotist dies or disconnects, then the hypnosis wears off.\\r\\n* Egotist and Executioner Target should no longer be able to become Traitor.\\r\\n* Traitor spawn is fixed.\\r\\n* Traitor\'s cooldown no longer drops down to 10 seconds when changing their role.\\r\\n* Bombs no longer trigger within meetings.\\r\\n* Bombs will appear for teammates correctly.\\r\\n* Miner vents are fixed in Weapons (Polus) and can no longer be placed inside doors.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Amnesiac takes away unique roles correctly again.\\r\\n* Plaguebearer infections do not spread from meeting kills.\\r\\n* Executioner and GA have better checks for their targets dying.\\r\\n* If the Amnesiac was a target for an Inquisitor, and they pick up the role of said Inquisitor, their role will be removed from the list of heretics.\\r\\n</details> \\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Lover death checks run on the host, removing the need for two separate death checks.\\r\\n* If a Scavenger has a lover, they will no longer target them.\\r\\n* It is no longer possible to have a neutral lover if the setting is disabled.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Rainbow text color in the host panel and the chat pop-ups are rainbow instead of black now.\\r\\n* Death Valley task is now accounted for correctly; fixes the red map and the task being inaccessible.\\r\\n* It is no longer possible to get Traitor, Lovers, Pestilence, or a killing target as GA when the respective options are set to 0%.\\r\\n* Hidden shields should no longer appear in the modifiers HUD.\\r\\n* The offset button no longer shows a comms symbol when comms are off.\\r\\n* Setting the amount of impostors via role list overrides vanilla settings now.\\r\\n* If you get shot out of a meeting, your buttons should no longer show up.\\r\\n* Game will no longer end within the exile screen (which affected Prosecutor in a 1v1).\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Task progress now shifts from red to yellow, to green.\\r\\n* Modifier assignment is now shuffled instead of being alphabetical.\\r\\n* There is now a tally for the number of tabs in the cosmetics menu.\\r\\n* In meetings, certain roles will show information, such as Doomsayer and Vigi seeing guesses needed/available, or for prosecutor uses, or even showing double shot usage for assassins.\\r\\n* First Round Shield was recoded to prevent it from breaking if the first player to die disconnected, and also keeps track of up to 4 players if the first dead player isn\'t in the next match.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions and Changes**</summary>\\r\\n* **Added:** Lovers can still kill each other by default, but this can be changed via a toggle.\\r\\n* **Added:** Cause of death is shown on the endscreen and in-game.\\r\\n* **Added:** Added an option for meeting deaths to add time to the vote timer.\\r\\n* **Added:** Added back \\"GA Target Knows\\" option.\\r\\n* **Changed:** Jester Haunt, Executioner Torment, and Phantom Spook no longer appear on round start; instead, a new button will appear to haunt/torment/spook a player of your choice.\\r\\n* **Changed:** Morphling Sample has no cooldown anymore.\\r\\n* **Changed:** Escapist Mark has no cooldown anymore.\\r\\n* **Changed:** Eclipsed and Flashed players can use their abilities again, but may not report bodies.\\r\\n* **Changed:** Double Shot is now an Assailant Modifier, applying to Impostors as well as Neutral Killers.\\r\\n* **Changed:** Investigator Footprints are now closer to how TOUR Footprints appear and act.\\r\\n* **Removed:** Impostors both being lovers can no longer happen as it simply life-links impostors to no benefit.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-102","metadata":{"permalink":"/docs.toum.gg/blog/update-102","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-07-04-update-102.md","source":"@site/blog/first-release/2025-07-04-update-102.md","title":"v1.0.2 Update","description":"Town of Us: Mira has updated to v1.0.2!","date":"2025-07-04T00:00:00.000Z","tags":[],"readingTime":2.73,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-102","title":"v1.0.2 Update","authors":"moon"},"unlisted":false,"prevItem":{"title":"v1.0.5 Update","permalink":"/docs.toum.gg/blog/update-105"},"nextItem":{"title":"v1.0.1 Update","permalink":"/docs.toum.gg/blog/update-101"}},"content":"## Town of Us: Mira has updated to [v1.0.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/v1.0.2)!\\r\\nThis update includes bug fixes and improvements.\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n  \\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Investigator footprints hide in comms properly and no longer error out.\\r\\n* Deputy camped notification should be sent to the correct player now.\\r\\n* Sheriff correct kills are checked correctly.\\r\\n* Sheriff no longer continues the game on misfire.\\r\\n* \\"Jailee Can\'t Use Public Chat\\" option has been fixed.\\r\\n* Prosecutor continues game.\\r\\n* Infinite Engineer vent uses no longer shows uses as \\"0\\".\\r\\n* Imitator should no longer be able to change roles if they have turned vamp or traitor.\\r\\n* Engineer/Plumber can no longer access vents through walls.\\r\\n* Amnesiac and Imitator no longer interfere when selecting.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* Hypnotised players should no longer be able to see player names.\\r\\n* Dead traitor should no longer be able to change their role.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Pestilence has Impostor vision.\\r\\n* Hacking a player should no longer affect meeting or ejection screen kills.\\r\\n</details> \\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Shy no longer applies onto Phantom/Haunter.\\r\\n* Egotist can no longer be traitor.\\r\\n* Egotist cannot leave the game if lovers are alive.\\r\\n* Egotists no longer show correct or incorrect kills.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Vent offset no longer shows a timer.\\r\\n* If impostors cannot see each others\' roles but know who they are, they can see each other in the team reveal properly.\\r\\n</details>\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* Cleric now tells you if the player you cleansed had no negative effects.\\r\\n* Task count is shown on the Taskbar tab itself.\\r\\n* Faction/Team modifiers are shown below role description in the role reveal screen.\\r\\n* Satellite now shows dead bodies on the map.\\r\\n* Tracker arrow delay and Shy options can go down to zero seconds.\\r\\n* End Game Timer options can go up to 30 minutes.\\r\\n* Sheriff Shoot, Button Barry, and Satellite Broadcast can be used immediately in Freeplay regardless of Round One settings.\\r\\n* Meeting kill animations are instant when there\'s less than 6 players.\\r\\n* End Game checks were moved around and should fix crashes on Epic Games.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions and Changes**</summary>\\r\\n* **Added:** End Game Timer now allows switching between \\"Game Draw\\" and \\"Impostor Win\\" on the timer ending.\\r\\n* **Added:** Scavenger now gets a HnS-like pop-up for their next target.\\r\\n* **Added:** Amnesiac gives feedback and will notify you when trying to remember Amnesiac.\\r\\n* **Added:** Better Airship options.\\r\\n* **Added:** Arrow Style option: Toggle between the default look, the arrow with a dark glow, a color glow, or use the old task arrows if you wish.\\r\\n* **Changed:** Inquisitor\'s \\"Stall Game\\" option is now only applicable in 1v1s or 2v1s.\\r\\n* **Changed:** Assassin\'s \\"Guess Spy / Investigator Modifier\\" options are now merged into one option that includes all Crewmate Utility Modifiers in general.\\r\\n* **Changed:** Just like in ToU:R, all button timers will now pause in vents (besides Glitch\'s buttons).\\r\\n* **Changed:** Imitator can no longer pick up Politician or Mayor (because they can stay as those roles forever).\\r\\n* **Removed:** `/sethost` command.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"update-101","metadata":{"permalink":"/docs.toum.gg/blog/update-101","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-06-30-update-101.md","source":"@site/blog/first-release/2025-06-30-update-101.md","title":"v1.0.1 Update","description":"Town of Us: Mira has updated to v1.0.1!","date":"2025-06-30T00:00:00.000Z","tags":[],"readingTime":2.36,"hasTruncateMarker":true,"authors":[{"name":"moon","title":"TOU Server Admin","url":"https://github.com/aquaamoon","page":{"permalink":"/docs.toum.gg/blog/authors/all-moon-articles"},"socials":{"github":"https://github.com/aquaamoon"},"imageURL":"https://github.com/aquaamoon.png","key":"moon"}],"frontMatter":{"slug":"update-101","title":"v1.0.1 Update","authors":["moon"]},"unlisted":false,"prevItem":{"title":"v1.0.2 Update","permalink":"/docs.toum.gg/blog/update-102"},"nextItem":{"title":"First Release!","permalink":"/docs.toum.gg/blog/first-release"}},"content":"## Town of Us: Mira has updated to v1.0.1!\\r\\n**Note:** This update requires a new install.\\r\\n\\r\\n### Changelog\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Role Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Crewmates**</summary>\\r\\n* Detective report settings are now toggled correctly.\\r\\n* Haunter can open Decontamination doors again!\\r\\n* Investigator footprints are hidden in comms sabotage.\\r\\n* Prosecutor\'s prosecution is always anonymous.\\r\\n* Prosecutor can no longer pros the skip button.\\r\\n* If you are jailed and your Jailor dies mid-meeting, your messages are not displaced into public chat.\\r\\n* Altruist revives dead lovers properly.\\r\\n* Imitator Mayor no longer reveals themselves to the crew as Imitator.\\r\\n* Imitator role change rpc has been fixed, shouldn\'t result in errors anymore.\\r\\n* Medium arrows are removed after a meeting.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Impostors**</summary>\\r\\n* A player that\'s destined to become Traitor no longer holds the game if they are dead.\\r\\n* Warlock no longer starts with a full charge after each meeting.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Neutrals**</summary>\\r\\n* Inquisitor checks if all their targets have died to determine if the game will end or not\\r\\n* Inquisitor Inquire uses no longer drain if someone was picked during the round already\\r\\n* Inquisitor report no longer duplicates the last role\\r\\n* Phantom will spawn correctly if Haunter failed to spawn\\r\\n* Phantom can open Decontamination doors again!\\r\\n* Soul Collected players will now hide in comms correctly\\r\\n</details> \\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Miscellaneous Bugfixes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Modifier Bug Fixes**</summary>\\r\\n* Celebrity no longer sends a report message when they are exiled.\\r\\n* In Freeplay, removing the Shy modifier no longer keeps your player or pet invisible.\\r\\n* Multitasker no longer makes security minigames transparent.\\r\\n* Taskmaster no longer finishes a task after the role intro.\\r\\n* Lovers die together and revive together properly.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Other Bug Fixes**</summary>\\r\\n* Spamming to join into a lobby is no longer possible, and will not queue a join attempt repeatedly.\\r\\n* Zooming in freeplay no longer shows broken shadows, instead opting to hide them.\\r\\n* Messages with 0 characters will no longer be parsed through private chats.\\r\\n* Long mode no longer trips up the game.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n  <summary>**Improvements and Changes**</summary>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Improvements**</summary>\\r\\n* The `/setname` command now has a limit of 12 characters and removes tmp text.\\r\\n* Lovers chatbox is hidden in the exile screen.\\r\\n* Colorblind text is now always capitalized in all menus.\\r\\n* Tawny and Gold color names have been swapped around.\\r\\n* More errors have been cleared up, so there will be less filler in logs and the game will be smoother.\\r\\n* Wiki hides the host player UI in the lobby.\\r\\n</details>\\r\\n\\r\\n<details className=\\"customdetails\\">\\r\\n<summary>**Additions and Changes**</summary>\\r\\n* **Added:** \\"Jailee Can Use Public Chat\\" toggle.\\r\\n* **Added:** New Colors!\\r\\n* **Added:** Long Horse April Fools (Long and Long Horse have issues with cosmetics, be aware of this).\\r\\n* **Removed:** `/sethost` command.\\r\\n</details>\\r\\n\\r\\n</details>\\r\\n\\r\\n{/* truncate */}"},{"id":"first-release","metadata":{"permalink":"/docs.toum.gg/blog/first-release","editUrl":"https://github.com/AU-Avengers/docs.toum.gg/blob/main/blog/first-release/2025-06-19-first-release.md","source":"@site/blog/first-release/2025-06-19-first-release.md","title":"First Release!","description":"Hey crewmates!","date":"2025-06-19T00:00:00.000Z","tags":[],"readingTime":0.54,"hasTruncateMarker":true,"authors":[{"name":"Atony","title":"Developer","url":"https://github.com/AtonyGit","page":{"permalink":"/docs.toum.gg/blog/authors/all-atony-articles"},"socials":{"x":"https://x.com/AtonyNothing","github":"https://github.com/AtonyGit"},"imageURL":"https://github.com/AtonyGit.png","key":"atony"},{"name":"AlchlcDvl","title":"Developer","url":"https://github.com/AlchlcDvl","page":{"permalink":"/docs.toum.gg/blog/authors/all-alchlcdvl-articles"},"socials":{"x":"https://x.com/alchlcdvl","github":"https://github.com/AlchlcDvl"},"imageURL":"https://github.com/AlchlcDvl.png","key":"alchlcdvl"}],"frontMatter":{"slug":"first-release","title":"First Release!","authors":["atony","alchlcdvl"]},"unlisted":false,"prevItem":{"title":"v1.0.1 Update","permalink":"/docs.toum.gg/blog/update-101"}},"content":"Hey crewmates!\\r\\n\\r\\nWe\'ve been hard at work in preparation for Town of Us: Mira\'s first public release, so we have now set up a wiki here for the community, which will contain all the same information as the In-Game WIki! Neat, right?\\r\\n\\r\\nThat\'s not all: We also have install guides (some courtesy of [Chloe](https://totallychloe.carrd.co/)) over in the [Installation Guide](/docs/install/intro) tab, as well as some of my own.\\r\\n\\r\\nWe hope you enjoy the release of TOU Mira, and as always, give feedback or file bug reports over on the [Discord Server](https://discord.gg/ugyc4EVUYZ), we appreciate all the feedback given to us!\\r\\n{/* truncate */}"}]}}')}}]);